<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{request}from'../../api/client';const dramas=ref<any[]>([]),selected=ref<number>(),episodes=ref<any[]>([]);async function loadDramas(){try{dramas.value=(await request('/api/v1/admin/dramas?page=1&page_size=100')).items||[]}catch{dramas.value=[]}}async function loadEpisodes(id:number){selected.value=id;try{episodes.value=(await request('/api/v1/admin/dramas/'+id+'/episodes?status=1')).items||[]}catch(e:any){ElMessage.error(e.message)}}loadDramas()</script>
<template><section><div class="title"><p>CONTENT / EPISODES</p><h1>剧集管理</h1><span>选择短剧查看真实剧集数据</span></div><el-card><el-select v-model="selected" placeholder="选择短剧" style="width:420px" @change="loadEpisodes"><el-option v-for="x in dramas" :key="x.id" :label="x.title" :value="x.id"/></el-select></el-card><el-card v-if="selected" class="panel"><el-table :data="episodes"><el-table-column prop="episode_no" label="集数"/><el-table-column prop="title" label="标题"/><el-table-column prop="duration_seconds" label="时长"/><el-table-column prop="video_url" label="视频地址"/></el-table><el-empty v-if="!episodes.length" description="暂无剧集"/></el-card></section></template>